-- public.fail_factor(p_skill double precision, p_difficulty double precision, p_tool_ql double precision, p_ease double precision, p_fail double precision, p_material double precision, p_mind double precision)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.fail_factor(p_skill double precision, p_difficulty double precision, p_tool_ql double precision DEFAULT 0, p_ease double precision DEFAULT 0, p_fail double precision DEFAULT 1, p_material double precision DEFAULT 0, p_mind double precision DEFAULT NULL::double precision)
 RETURNS TABLE(id text, n double precision, cost double precision)
 LANGUAGE sql
 STABLE
AS $function$
  with t (o, id, n, best) as (
    select 1, 'skill', p_skill, skill_odds(skill_top(), p_difficulty, p_tool_ql, p_ease)
    union all select 2, 'tool', p_tool_ql, skill_odds(p_skill, p_difficulty, ql_top(), p_ease) where p_tool_ql > 0
    union all select 3, 'material', p_material, skill_odds(p_skill, p_difficulty - p_material, p_tool_ql, p_ease) where p_material > 0
    union all select 4, 'mind', p_mind, skill_odds(p_skill, p_difficulty, p_tool_ql, mind_ease_at(skill_top())) where p_mind is not null
  ), c as (
    select t.o, t.id, t.n, p_fail * (t.best - skill_odds(p_skill, p_difficulty, p_tool_ql, p_ease)) as cost from t
  )
  select c.id, c.n, c.cost from c where c.cost >= fail_least() order by c.cost desc, c.o limit 1
$function$
